SELECT CASE WHEN s.rating >= 4.5 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(ss.sale_date) AS last_sale_date FROM store_sales ss INNER JOIN products p ON ss.product_id = p.id LEFT OUTER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.5 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END;
